    align-items: center;
    display: flex;
    flex-wrap: wrap;
    gap: var(--inline-space-half);
    inline-size: 100%;
    z-index: 3;

    &:has([open]) {
      z-index: var(--z-popup);
    }

    &:not(:has(.reaction)) {
      inline-size: auto;

