          content: "";
          inset: 0 calc(-1 * var(--card-padding-inline)) auto;
          position: absolute;
        }

        @media (any-hover: none) {
          --reaction-size: 2.25rem;
        }
      }

      &:not(:has(.reaction)) {
        margin: 0;

        .reactions__trigger {
          --btn-border-color: var(--color-ink-light);
        }
      }
    }

    .reaction__popup.popup {
      inline-size: max-content;
    }

    .card__zoom-bg-btn {
      grid-area: bg-zoom;
    }

